//! Transclusion — read-only, section-level.
//!
//! A *transclusion* inlines the rendered content of one document (or a
//! section of it) into another by reference, so a long-form read is
//! assembled at render time from many small source files while each
//! source keeps its own identity. The design is set out in an internal
//! design decision (`transclusion`); this module is its implementation.
//!
//! This module is the **shared core** that both rendering surfaces drive:
//!
//! - The **weave** step (`x0k-tangle::region_weave`, the literate-region
//!   to static-site renderer) resolves transclusions to inlined markdown
//!   *before* weaving to HTML, so the web document renderer receives
//!   pre-resolved content.
//! - The **native** doc-viewer (the desktop application's document
//!   widget) resolves the same references through the same core so the
//!   native structural render matches the web.
//!
//! It lives in `x0k-folio` (not `x0k-tangle`) so the native widgets
//! and doc-viewer can consume it without taking a dependency on the weave
//! crate.
//!
//! # Granularity
//!
//! Addressing is **section-level**: a reference is a folio URI
//! optionally suffixed with a `#heading-path` anchor. With no anchor the
//! whole target body is inlined. Block-level addressing is designed-in
//! (the anchor model is the same heading-path scheme `block_segment` mints)
//! but only section/whole-doc resolve today.
//!
//! # Two declaration forms
//!
//! 1. Frontmatter `transcludes:` sequence in the `x0k:` envelope — order
//!    is the reading order; each entry becomes a `transcludes` edge and is
//!    appended (in order) to the resolved body.
//! 2. Inline fence in the body:
//!    ```text
//!    x0k:transclude {ref="x0k:design/places#brief"}
//!    ```
//!    Resolved in place.
//!
//! # Recursion, cycles, depth
//!
//! A transcluded document may itself transclude others, so resolution is
//! recursive. Cycle detection (a document may not transitively transclude
//! itself) degrades the offending reference to a plain link and records a
//! warning; a depth bound caps runaway nesting the same way.

use std::collections::HashSet;

/// Maximum transclusion nesting depth. Beyond this, references degrade to
/// links (mirrors the WorldSpec portal-recursion depth bound discipline).
pub const MAX_TRANSCLUDE_DEPTH: usize = 8;

/// A parsed transclusion reference: a folio URI plus an optional
/// `#heading-path` section anchor.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TranscludeRef {
    /// The target document URI, e.g. `x0k:wiki/keyhive`.
    pub uri: String,
    /// The section anchor (heading-path slug) after `#`, if any. `None`
    /// means the whole document.
    pub anchor: Option<String>,
}

impl TranscludeRef {
    /// Parse a `ref` string into a URI + optional anchor. Splits on the
    /// first `#`. Leading/trailing whitespace is trimmed.
    pub fn parse(reference: &str) -> Self {
        let reference = reference.trim();
        match reference.split_once('#') {
            Some((uri, anchor)) => TranscludeRef {
                uri: uri.trim().to_string(),
                anchor: {
                    let a = anchor.trim();
                    if a.is_empty() {
                        None
                    } else {
                        Some(a.to_string())
                    }
                },
            },
            None => TranscludeRef {
                uri: reference.to_string(),
                anchor: None,
            },
        }
    }

    /// Re-serialize to the canonical `uri#anchor` form (or just `uri`).
    pub fn to_ref_string(&self) -> String {
        match &self.anchor {
            Some(a) => format!("{}#{a}", self.uri),
            None => self.uri.clone(),
        }
    }
}

/// A source of document bodies for resolution. Implementors map a
/// folio URI to that document's **body markdown** (frontmatter
/// envelope already stripped). Returning `None` means "no such document
/// in scope" — the reference degrades to a link with a warning.
pub trait DocSource {
    /// Return the target document's body markdown (frontmatter stripped),
    /// or `None` if the URI does not resolve within this source.
    fn body(&self, uri: &str) -> Option<String>;
}

/// A warning surfaced during resolution. Non-fatal: the corresponding
/// reference was degraded to a plain link rather than inlined.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TranscludeWarning {
    /// The reference's URI did not resolve in the `DocSource`.
    Unresolved { reference: String },
    /// The `#anchor` section was not found in the (resolved) target.
    SectionNotFound { reference: String },
    /// Resolving this reference would (transitively) transclude a
    /// document already on the resolution stack — a cycle.
    Cycle { reference: String },
    /// The depth bound was hit before this reference could be resolved.
    DepthExceeded { reference: String },
}

impl TranscludeWarning {
    /// The reference string the warning is about.
    pub fn reference(&self) -> &str {
        match self {
            TranscludeWarning::Unresolved { reference }
            | TranscludeWarning::SectionNotFound { reference }
            | TranscludeWarning::Cycle { reference }
            | TranscludeWarning::DepthExceeded { reference } => reference,
        }
    }
}

/// The product of resolving a spine document's transclusions.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resolved {
    /// The spine body with all transclusions inlined.
    pub body: String,
    /// Non-fatal warnings (cycles, unresolved refs, missing sections);
    /// each corresponds to a reference that degraded to a link.
    pub warnings: Vec<TranscludeWarning>,
    /// The set of URIs transcluded anywhere in the resolution, deduped and
    /// sorted. Useful to the weave for harvesting / edge emission.
    pub transcluded_uris: Vec<String>,
}

/// Extract the `transcludes:` sequence from a folio/v1 frontmatter
/// envelope. Order is preserved (it is the reading order). Returns an
/// empty vec when there is no frontmatter or no `transcludes:` key.
///
/// The scan is line-oriented and tolerant: it looks inside the leading
/// `---`-delimited block for a `transcludes:` key whose value is a YAML
/// block sequence of `- <ref>` items (the canonical authoring shape).
pub fn frontmatter_transcludes(content: &str) -> Vec<String> {
    let Some(envelope) = frontmatter_block(content) else {
        return Vec::new();
    };
    let mut out = Vec::new();
    let mut in_seq = false;
    // Indentation (column) of the `transcludes:` key, so we know when the
    // sequence ends (a key at the same-or-shallower indent).
    let mut key_indent = 0usize;
    for raw in envelope.lines() {
        let indent = raw.len() - raw.trim_start().len();
        let line = raw.trim_start();
        if !in_seq {
            if line == "transcludes:"
                || line.starts_with("transcludes:")
                    && line["transcludes:".len()..].trim().is_empty()
            {
                in_seq = true;
                key_indent = indent;
            }
            continue;
        }
        // We are inside the sequence. A `- item` line that is indented
        // deeper than the key continues the sequence.
        if line.starts_with("- ") && indent > key_indent {
            let item = line[2..].trim();
            let item = item.trim_matches('"').trim_matches('\'').trim();
            if !item.is_empty() {
                out.push(item.to_string());
            }
            continue;
        }
        if line.is_empty() {
            // Blank line inside the sequence — tolerate and keep scanning.
            continue;
        }
        // Any other content at the key's indent (or shallower) ends the
        // sequence.
        if indent <= key_indent {
            break;
        }
    }
    out
}

/// Return the inner text of the leading `---`-delimited frontmatter block,
/// or `None` when the content does not open with one.
fn frontmatter_block(content: &str) -> Option<&str> {
    let rest = content.strip_prefix("---")?;
    // The opening `---` must be followed by a newline.
    let rest = rest
        .strip_prefix('\n')
        .or_else(|| rest.strip_prefix("\r\n"))?;
    let end = rest.find("\n---")?;
    Some(&rest[..end])
}

/// One inline transclude fence found in a body, with its byte range so the
/// caller can splice a replacement in place.
#[derive(Debug, Clone, PartialEq, Eq)]
struct FenceMatch {
    /// Byte offset of the start of the fence's opening ``` ``` ``` line.
    start: usize,
    /// Byte offset just past the fence's closing ``` ``` ``` line.
    end: usize,
    /// The parsed `ref="..."` value.
    reference: String,
}

/// Find every `x0k:transclude {ref="..."}` fenced block in a markdown
/// body. The fence info string must contain the `x0k:transclude` marker
/// and a `ref="..."` attribute. The fence body (between the open and close
/// ``` ``` ```) is ignored — the reference is the payload.
fn find_transclude_fences(body: &str) -> Vec<FenceMatch> {
    let mut out = Vec::new();
    let bytes = body.as_bytes();
    let mut line_start = 0usize;
    while line_start < bytes.len() {
        let line_end = body[line_start..]
            .find('\n')
            .map(|i| line_start + i)
            .unwrap_or(bytes.len());
        let line = &body[line_start..line_end];
        let trimmed = line.trim_start();
        if let Some(info) = trimmed.strip_prefix("```") {
            if info.contains("x0k:transclude") {
                if let Some(reference) = extract_ref_attr(info) {
                    // Find the closing fence line (a line whose trim is ```).
                    let mut scan = line_end + 1;
                    let mut close_end = bytes.len();
                    while scan <= bytes.len() {
                        let next_end = body[scan.min(bytes.len())..]
                            .find('\n')
                            .map(|i| scan + i)
                            .unwrap_or(bytes.len());
                        let l = &body[scan.min(bytes.len())..next_end];
                        if l.trim() == "```" {
                            close_end = (next_end + 1).min(bytes.len());
                            break;
                        }
                        if next_end >= bytes.len() {
                            close_end = bytes.len();
                            break;
                        }
                        scan = next_end + 1;
                    }
                    out.push(FenceMatch {
                        start: line_start,
                        end: close_end,
                        reference,
                    });
                    line_start = close_end;
                    continue;
                }
            }
        }
        line_start = line_end + 1;
    }
    out
}

/// Pull the `ref="..."` attribute value out of a `x0k:transclude` fence
/// info string (e.g. `x0k:transclude {ref="x0k:design/a#brief"}`). Public
/// so the native markdown parser can recognize the fence and mint a
/// `StructuralBlock::Transclusion` without re-implementing the scan.
/// Returns `None` when no `ref` attribute is present.
pub fn extract_fence_ref(info: &str) -> Option<String> {
    extract_ref_attr(info)
}

/// Pull the `ref="..."` (or `ref='...'`) attribute value out of a fence
/// info string. Returns `None` when absent.
fn extract_ref_attr(info: &str) -> Option<String> {
    let idx = info.find("ref")?;
    let after = &info[idx + 3..];
    let after = after.trim_start();
    let after = after.strip_prefix('=')?.trim_start();
    let quote = after.chars().next()?;
    if quote != '"' && quote != '\'' {
        return None;
    }
    let rest = &after[1..];
    let end = rest.find(quote)?;
    Some(rest[..end].trim().to_string())
}

/// Extract a section from a markdown body by heading-path anchor.
///
/// The anchor matches the slug of a heading (the same slug scheme
/// `block_segment` mints). The section runs from the matched heading up to
/// (but not including) the next heading at the same-or-shallower level.
/// The heading line itself is included so the inlined section keeps its
/// title. Returns `None` when no heading slugs to `anchor`.
///
/// The match is by single heading slug: a multi-segment anchor
/// (`parent/child`) matches the final segment.
pub fn extract_section(body: &str, anchor: &str) -> Option<String> {
    let lines: Vec<&str> = body.lines().collect();
    let (start, end) = find_section_range(&lines, anchor)?;
    Some(lines[start..end].join("\n"))
}

/// Find the `[start, end)` line range of the section addressed by
/// `anchor` (a heading-path slug; the final segment matches a heading
/// slug). The range begins at the matched heading line and ends just
/// before the next heading at the same-or-shallower level (or at the end
/// of the body). Returns `None` when no heading slugs to `anchor`.
///
/// Shared by [`extract_section`] (read) and [`replace_section`]
/// (edit-through write) so the two stay in lockstep — an edit replaces
/// exactly the span a transclusion inlined.
fn find_section_range(lines: &[&str], anchor: &str) -> Option<(usize, usize)> {
    // The anchor may be a heading path (`a/b/c`); match its final segment
    // against individual heading slugs.
    let target = anchor.rsplit('/').next().unwrap_or(anchor);
    let mut start: Option<usize> = None;
    let mut start_level = 0usize;
    for (i, line) in lines.iter().enumerate() {
        if let Some((level, text)) = heading_of(line) {
            if let Some(s) = start {
                if level <= start_level {
                    // Next heading at same-or-shallower level closes the section.
                    return Some((s, i));
                }
            } else if heading_slug(text) == target {
                start = Some(i);
                start_level = level;
            }
        }
    }
    start.map(|s| (s, lines.len()))
}

/// Replace the section addressed by `anchor` in `body` with
/// `new_section`, returning the rewritten body. This is the
/// **edit-through** inverse of [`extract_section`]: an edit made to a
/// transcluded region is written back to the *source* document by
/// splicing the new section content over exactly the span the
/// transclusion inlined.
///
/// `new_section` is the full replacement markdown for the section
/// (including its heading line, as `extract_section` returns it). The
/// surrounding body — everything before the section's heading and
/// everything from the next same-or-shallower heading onward — is
/// preserved verbatim. Returns `None` when `anchor` resolves to no
/// section (the caller surfaces this as "section not found", refusing
/// the write rather than appending).
///
/// Per the transclusion design's "edit-through" rule: the edit lands on
/// the source's canonical home, so every reading updates.
pub fn replace_section(body: &str, anchor: &str, new_section: &str) -> Option<String> {
    let lines: Vec<&str> = body.lines().collect();
    let (start, end) = find_section_range(&lines, anchor)?;
    let mut out: Vec<&str> = Vec::with_capacity(lines.len());
    out.extend_from_slice(&lines[..start]);
    // Splice the new section's lines in place of the old span.
    let new_lines: Vec<&str> = new_section.lines().collect();
    out.extend_from_slice(&new_lines);
    out.extend_from_slice(&lines[end..]);
    let mut joined = out.join("\n");
    // Preserve a trailing newline if the original body had one (the body
    // is the post-frontmatter region; decision/wiki files end with `\n`).
    if body.ends_with('\n') && !joined.ends_with('\n') {
        joined.push('\n');
    }
    Some(joined)
}

/// If `line` is an ATX heading (`#`..`######` followed by a space), return
/// `(level, heading-text)`.
fn heading_of(line: &str) -> Option<(usize, &str)> {
    let trimmed = line.trim_start();
    let hashes = trimmed.chars().take_while(|&c| c == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let rest = &trimmed[hashes..];
    let text = rest.strip_prefix(' ')?;
    Some((hashes, text.trim()))
}

/// Slugify a heading's text. MUST match `block_segment::slug` so anchors
/// minted by the in-prose-authoring heading-path scheme resolve here.
pub fn heading_slug(text: &str) -> String {
    let mut out = String::new();
    let mut prev_dash = false;
    for ch in text.chars() {
        if ch.is_alphanumeric() {
            out.extend(ch.to_lowercase());
            prev_dash = false;
        } else if !prev_dash && !out.is_empty() {
            out.push('-');
            prev_dash = true;
        }
    }
    let trimmed = out.trim_matches('-');
    let capped: String = trimmed.chars().take(40).collect();
    // Trim AGAIN after the cap: trimming only before it lets truncation land
    // mid-word and leave a trailing dash, so a long heading slugs to
    // `...-the-vocabulary-`. The anchor is a public address — a transclusion
    // ref and a publication's section selector both spell it — so a dangling
    // dash is not cosmetic.
    let capped = capped.trim_matches('-');
    if capped.is_empty() {
        "untitled".to_string()
    } else {
        capped.to_string()
    }
}

/// Resolve all transclusions in a spine document.
///
/// `spine_content` is the full spine file (frontmatter + body); the
/// frontmatter `transcludes:` sequence is read from it and its bodies
/// appended (in order) after inline fences in the body are resolved.
/// `frontmatter_refs` may be passed pre-extracted (e.g. by the weave,
/// which already parsed the envelope); pass `None` to extract them here.
pub fn resolve(
    spine_content: &str,
    frontmatter_refs: Option<Vec<String>>,
    source: &dyn DocSource,
) -> Resolved {
    let (_, body) = split_body(spine_content);
    let fm_refs = frontmatter_refs.unwrap_or_else(|| frontmatter_transcludes(spine_content));

    let mut warnings = Vec::new();
    let mut transcluded: HashSet<String> = HashSet::new();
    // The spine's own URI isn't known here; the visited-stack starts empty
    // and accrues each resolved URI so a target can't re-include an
    // ancestor. The spine itself is guarded by the weave passing it as the
    // first visited entry when known (resolve_with_root).
    let mut visited: HashSet<String> = HashSet::new();

    let resolved_body = resolve_body(
        body,
        source,
        0,
        &mut visited,
        &mut warnings,
        &mut transcluded,
    );

    // Append frontmatter transclusions in reading order.
    let mut out = resolved_body;
    for r in &fm_refs {
        let section = resolve_ref(r, source, 0, &mut visited, &mut warnings, &mut transcluded);
        if !out.is_empty() && !out.ends_with("\n\n") {
            if out.ends_with('\n') {
                out.push('\n');
            } else {
                out.push_str("\n\n");
            }
        }
        out.push_str(&section);
        if !out.ends_with('\n') {
            out.push('\n');
        }
    }

    let mut transcluded_uris: Vec<String> = transcluded.into_iter().collect();
    transcluded_uris.sort();
    Resolved {
        body: out,
        warnings,
        transcluded_uris,
    }
}

/// Like [`resolve`], but seeds the visited-stack with the spine's own URI
/// so a direct or transitive self-transclusion is detected as a cycle.
pub fn resolve_with_root(
    spine_content: &str,
    root_uri: &str,
    frontmatter_refs: Option<Vec<String>>,
    source: &dyn DocSource,
) -> Resolved {
    let (_, body) = split_body(spine_content);
    let fm_refs = frontmatter_refs.unwrap_or_else(|| frontmatter_transcludes(spine_content));

    let mut warnings = Vec::new();
    let mut transcluded: HashSet<String> = HashSet::new();
    let mut visited: HashSet<String> = HashSet::new();
    visited.insert(root_uri.to_string());

    let resolved_body = resolve_body(
        body,
        source,
        0,
        &mut visited,
        &mut warnings,
        &mut transcluded,
    );

    let mut out = resolved_body;
    for r in &fm_refs {
        let section = resolve_ref(r, source, 0, &mut visited, &mut warnings, &mut transcluded);
        if !out.is_empty() {
            if out.ends_with('\n') {
                out.push('\n');
            } else {
                out.push_str("\n\n");
            }
        }
        out.push_str(&section);
        if !out.ends_with('\n') {
            out.push('\n');
        }
    }

    let mut transcluded_uris: Vec<String> = transcluded.into_iter().collect();
    transcluded_uris.sort();
    Resolved {
        body: out,
        warnings,
        transcluded_uris,
    }
}

/// Resolve every inline fence in `body`, splicing the resolved content in
/// place. Recursion is bounded by `depth` and guarded by `visited`.
fn resolve_body(
    body: &str,
    source: &dyn DocSource,
    depth: usize,
    visited: &mut HashSet<String>,
    warnings: &mut Vec<TranscludeWarning>,
    transcluded: &mut HashSet<String>,
) -> String {
    let fences = find_transclude_fences(body);
    if fences.is_empty() {
        return body.to_string();
    }
    let mut out = String::with_capacity(body.len());
    let mut cursor = 0usize;
    for f in fences {
        out.push_str(&body[cursor..f.start]);
        let section = resolve_ref(&f.reference, source, depth, visited, warnings, transcluded);
        // Ensure the inlined section is block-separated from surrounding
        // prose.
        if !out.is_empty() && !out.ends_with('\n') {
            out.push('\n');
        }
        out.push_str(&section);
        if !section.ends_with('\n') {
            out.push('\n');
        }
        cursor = f.end;
    }
    out.push_str(&body[cursor..]);
    out
}

/// Resolve one reference to its inlined markdown (recursively). On any
/// degradation (unresolved, missing section, cycle, depth) returns a plain
/// markdown link to the target and records a warning.
fn resolve_ref(
    reference: &str,
    source: &dyn DocSource,
    depth: usize,
    visited: &mut HashSet<String>,
    warnings: &mut Vec<TranscludeWarning>,
    transcluded: &mut HashSet<String>,
) -> String {
    let parsed = TranscludeRef::parse(reference);

    if depth >= MAX_TRANSCLUDE_DEPTH {
        warnings.push(TranscludeWarning::DepthExceeded {
            reference: reference.to_string(),
        });
        return degrade_to_link(&parsed);
    }
    if visited.contains(&parsed.uri) {
        warnings.push(TranscludeWarning::Cycle {
            reference: reference.to_string(),
        });
        return degrade_to_link(&parsed);
    }

    let Some(target_body) = source.body(&parsed.uri) else {
        warnings.push(TranscludeWarning::Unresolved {
            reference: reference.to_string(),
        });
        return degrade_to_link(&parsed);
    };

    // Extract the addressed section (or the whole body).
    let section = match &parsed.anchor {
        Some(anchor) => match extract_section(&target_body, anchor) {
            Some(s) => s,
            None => {
                warnings.push(TranscludeWarning::SectionNotFound {
                    reference: reference.to_string(),
                });
                return degrade_to_link(&parsed);
            }
        },
        None => target_body.clone(),
    };

    transcluded.insert(parsed.uri.clone());

    // Recurse: the extracted section may itself transclude. Guard the
    // current URI on the visited stack for the duration of the recursion.
    visited.insert(parsed.uri.clone());
    let resolved = resolve_body(&section, source, depth + 1, visited, warnings, transcluded);
    visited.remove(&parsed.uri);
    resolved
}

/// Degrade a reference to a plain markdown link (the "go there" fallback).
fn degrade_to_link(parsed: &TranscludeRef) -> String {
    let label = parsed
        .uri
        .rsplit('/')
        .next()
        .filter(|s| !s.is_empty())
        .unwrap_or(parsed.uri.as_str());
    format!("[{label}]({})", parsed.to_ref_string())
}

/// Split a folio/v1 file into `(frontmatter, body)`. Mirrors the
/// weave's `split_body` so resolution sees the same body the renderer does.
pub fn split_body(content: &str) -> (Option<&str>, &str) {
    if !content.starts_with("---") {
        return (None, content);
    }
    let after_first = &content[3..];
    if let Some(end) = after_first.find("\n---") {
        let yaml = &after_first[..end];
        let body_start = 3 + end + 4;
        let body = if body_start < content.len() {
            &content[body_start..]
        } else {
            ""
        };
        let body = body.strip_prefix('\n').unwrap_or(body);
        (Some(yaml), body)
    } else {
        (None, content)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    /// In-memory `DocSource` over URI → full-file content. `body` strips
    /// the frontmatter the same way the real renderer does.
    struct MapSource(HashMap<String, String>);

    impl DocSource for MapSource {
        fn body(&self, uri: &str) -> Option<String> {
            self.0.get(uri).map(|c| split_body(c).1.to_string())
        }
    }

    fn src(pairs: &[(&str, &str)]) -> MapSource {
        MapSource(
            pairs
                .iter()
                .map(|(k, v)| (k.to_string(), v.to_string()))
                .collect(),
        )
    }

    #[test]
    fn parse_ref_splits_uri_and_anchor() {
        assert_eq!(
            TranscludeRef::parse("x0k:wiki/keyhive"),
            TranscludeRef {
                uri: "x0k:wiki/keyhive".into(),
                anchor: None
            }
        );
        assert_eq!(
            TranscludeRef::parse("x0k:design/places#brief"),
            TranscludeRef {
                uri: "x0k:design/places".into(),
                anchor: Some("brief".into())
            }
        );
        // Empty anchor after `#` → None.
        assert_eq!(TranscludeRef::parse("x0k:wiki/x#").anchor, None);
    }

    #[test]
    fn frontmatter_transcludes_in_reading_order() {
        let content = "---\nx0k:\n  format: folio/v1\n  id: x0k:wiki/spine\n  type: wiki\n  status: stable\n  transcludes:\n    - x0k:design/a#brief\n    - x0k:design/b#brief\n  edges:\n    cites:\n      - x0k:wiki/x\n---\n\n# Spine\n\nBody.\n";
        let refs = frontmatter_transcludes(content);
        assert_eq!(refs, vec!["x0k:design/a#brief", "x0k:design/b#brief"]);
    }

    #[test]
    fn find_fences_extracts_ref() {
        let body = "Intro.\n\n```x0k:transclude {ref=\"x0k:design/a#brief\"}\n```\n\nOutro.\n";
        let fences = find_transclude_fences(body);
        assert_eq!(fences.len(), 1);
        assert_eq!(fences[0].reference, "x0k:design/a#brief");
    }

    #[test]
    fn extract_section_by_heading_slug() {
        let body =
            "# Title\n\nlead\n\n## Brief\n\nbrief body\nmore brief\n\n## Purpose\n\npurpose body\n";
        let s = extract_section(body, "brief").unwrap();
        assert!(s.starts_with("## Brief"));
        assert!(s.contains("brief body"));
        assert!(s.contains("more brief"));
        // Stops at the next same-level heading.
        assert!(!s.contains("Purpose"));
        assert!(!s.contains("purpose body"));
    }

    #[test]
    fn extract_section_includes_deeper_subsections() {
        let body = "## A\n\na body\n\n### A.1\n\nsub body\n\n## B\n\nb body\n";
        let s = extract_section(body, "a").unwrap();
        assert!(s.contains("### A.1"));
        assert!(s.contains("sub body"));
        assert!(!s.contains("## B"));
    }

    #[test]
    fn extract_section_missing_returns_none() {
        let body = "## A\n\nbody\n";
        assert!(extract_section(body, "nonexistent").is_none());
    }

    #[test]
    fn resolve_inline_fence_inlines_section() {
        let a = "---\nx0k:\n  id: x0k:design/a\n---\n\n# A\n\n## Brief\n\nA's brief.\n\n## Other\n\nnope\n";
        let spine = "Intro.\n\n```x0k:transclude {ref=\"x0k:design/a#brief\"}\n```\n\nOutro.\n";
        let source = src(&[("x0k:design/a", a)]);
        let r = resolve(spine, Some(vec![]), &source);
        assert!(r.body.contains("A's brief."));
        assert!(r.body.contains("Intro."));
        assert!(r.body.contains("Outro."));
        assert!(!r.body.contains("nope"));
        assert!(r.warnings.is_empty());
        assert_eq!(r.transcluded_uris, vec!["x0k:design/a".to_string()]);
    }

    #[test]
    fn resolve_frontmatter_refs_appended_in_order() {
        let a = "---\nx0k:\n  id: x0k:design/a\n---\n\n## Brief\n\nAlpha brief.\n";
        let b = "---\nx0k:\n  id: x0k:design/b\n---\n\n## Brief\n\nBeta brief.\n";
        let spine = "---\nx0k:\n  id: x0k:wiki/spine\n  transcludes:\n    - x0k:design/a#brief\n    - x0k:design/b#brief\n---\n\n# Spine\n\nConnective prose.\n";
        let source = src(&[("x0k:design/a", a), ("x0k:design/b", b)]);
        let r = resolve(spine, None, &source);
        let alpha = r.body.find("Alpha brief.").unwrap();
        let beta = r.body.find("Beta brief.").unwrap();
        assert!(alpha < beta, "reading order preserved");
        assert!(r.warnings.is_empty());
    }

    #[test]
    fn recursive_resolution_inlines_nested() {
        // a transcludes b; spine transcludes a.
        let a = "---\nx0k:\n  id: x0k:design/a\n---\n\n## Brief\n\nA top.\n\n```x0k:transclude {ref=\"x0k:design/b#brief\"}\n```\n";
        let b = "---\nx0k:\n  id: x0k:design/b\n---\n\n## Brief\n\nB nested.\n";
        let spine = "```x0k:transclude {ref=\"x0k:design/a#brief\"}\n```\n";
        let source = src(&[("x0k:design/a", a), ("x0k:design/b", b)]);
        let r = resolve(spine, Some(vec![]), &source);
        assert!(r.body.contains("A top."));
        assert!(r.body.contains("B nested."));
        assert!(r.warnings.is_empty());
        let mut uris = r.transcluded_uris.clone();
        uris.sort();
        assert_eq!(uris, vec!["x0k:design/a", "x0k:design/b"]);
    }

    #[test]
    fn cycle_degrades_to_link_with_warning() {
        // a transcludes b; b transcludes a → cycle when b re-includes a.
        let a = "---\nx0k:\n  id: x0k:design/a\n---\n\n## Brief\n\nA.\n\n```x0k:transclude {ref=\"x0k:design/b#brief\"}\n```\n";
        let b = "---\nx0k:\n  id: x0k:design/b\n---\n\n## Brief\n\nB.\n\n```x0k:transclude {ref=\"x0k:design/a#brief\"}\n```\n";
        let spine = "```x0k:transclude {ref=\"x0k:design/a#brief\"}\n```\n";
        let source = src(&[("x0k:design/a", a), ("x0k:design/b", b)]);
        let r = resolve(spine, Some(vec![]), &source);
        // The cycle back to a degrades to a link, not an infinite inline.
        assert!(r.body.contains("A."));
        assert!(r.body.contains("B."));
        assert!(r
            .warnings
            .iter()
            .any(|w| matches!(w, TranscludeWarning::Cycle { .. })));
        // The degraded link is present.
        assert!(r.body.contains("](x0k:design/a#brief)"));
    }

    #[test]
    fn self_transclusion_is_a_cycle() {
        let spine = "---\nx0k:\n  id: x0k:wiki/spine\n---\n\n# Spine\n\n```x0k:transclude {ref=\"x0k:wiki/spine\"}\n```\n";
        let source = src(&[("x0k:wiki/spine", spine)]);
        let r = resolve_with_root(spine, "x0k:wiki/spine", Some(vec![]), &source);
        assert!(r
            .warnings
            .iter()
            .any(|w| matches!(w, TranscludeWarning::Cycle { .. })));
    }

    #[test]
    fn unresolved_ref_degrades_to_link() {
        let spine = "```x0k:transclude {ref=\"x0k:design/missing#brief\"}\n```\n";
        let source = src(&[]);
        let r = resolve(spine, Some(vec![]), &source);
        assert!(r
            .warnings
            .iter()
            .any(|w| matches!(w, TranscludeWarning::Unresolved { .. })));
        assert!(r.body.contains("](x0k:design/missing#brief)"));
    }

    #[test]
    fn whole_doc_transclusion_when_no_anchor() {
        let a = "---\nx0k:\n  id: x0k:wiki/a\n---\n\n# A\n\nWhole body here.\n";
        let spine = "```x0k:transclude {ref=\"x0k:wiki/a\"}\n```\n";
        let source = src(&[("x0k:wiki/a", a)]);
        let r = resolve(spine, Some(vec![]), &source);
        assert!(r.body.contains("Whole body here."));
        assert!(r.body.contains("# A"));
    }

    #[test]
    fn replace_section_writes_back_only_the_addressed_span() {
        // Edit-through: replacing `## Brief` leaves the rest of the body
        // (lead, `## Purpose`) untouched.
        let body = "# Title\n\nlead\n\n## Brief\n\nold brief body\n\n## Purpose\n\npurpose body\n";
        let new = "## Brief\n\nNEW brief body\n";
        let out = replace_section(body, "brief", new).unwrap();
        assert!(out.contains("NEW brief body"));
        assert!(!out.contains("old brief body"));
        // Surrounding sections preserved.
        assert!(out.contains("# Title"));
        assert!(out.contains("lead"));
        assert!(out.contains("## Purpose"));
        assert!(out.contains("purpose body"));
        // The replacement round-trips: extracting the section now yields
        // the new content.
        let re = extract_section(&out, "brief").unwrap();
        assert!(re.contains("NEW brief body"));
        assert!(!re.contains("old brief body"));
    }

    #[test]
    fn replace_section_missing_anchor_refuses() {
        let body = "## A\n\nbody\n";
        assert!(replace_section(body, "nonexistent", "## A\n\nx\n").is_none());
    }

    #[test]
    fn replace_section_preserves_trailing_newline() {
        let body = "## A\n\nbody\n";
        let out = replace_section(body, "a", "## A\n\nnew\n").unwrap();
        assert!(out.ends_with('\n'));
    }

    #[test]
    fn replace_whole_doc_when_anchor_is_only_section() {
        // A section that runs to the end of the body replaces cleanly.
        let body = "## Only\n\noriginal\n";
        let out = replace_section(body, "only", "## Only\n\nrewritten\n").unwrap();
        assert_eq!(out, "## Only\n\nrewritten\n");
    }

    #[test]
    fn heading_slug_trims_a_dash_the_cap_left_behind() {
        // 40 chars lands mid-word here, and the char at the cap is a dash.
        // Before the second trim this slugged to `...-the-vocabulary-`.
        let s = heading_slug("Check a document against the vocabulary shipped beside it");
        assert!(!s.ends_with('-'), "slug {s} ends in a dash");
        assert!(s.chars().count() <= 40);
    }

    #[test]
    fn heading_slug_matches_block_segment_scheme() {
        assert_eq!(heading_slug("Open Questions"), "open-questions");
        assert_eq!(
            heading_slug("The principle: include, don't copy"),
            "the-principle-include-don-t-copy"
        );
        assert_eq!(heading_slug("Brief"), "brief");
    }
}
